import sympy as S
from fractions import Fraction as F
from itertools import combinations
from .authoring import maker,finish
from .common import section
q=maker('spatial-geometry',['unfolding','cross sections','volume scaling'])
sqrt=S.sqrt
p=[
q(1,r'A rectangular box has side lengths 2,3,6. Find its space diagonal.',7,[(sqrt(13),'Use only one face diagonal.'),(11,'Add edge lengths.'),(sqrt(40),'Omit one dimension.'),(49,'Report the squared distance.')],[r'A base-face diagonal has squared length 2²+3²=13.',r'It is perpendicular to the edge of length six.',r'The space diagonal is √(13+36)=7.'],['Build one right triangle in a face, then a second in space.','The vertical edge is perpendicular to the entire base plane.'],'Apply Pythagoras across two perpendicular planes.',lambda:S.Point3D(0,0,0).distance(S.Point3D(2,3,6)),'Independent three-dimensional coordinate distance.',2),
q(2,r'An ant walks on the surface of a rectangular box with side lengths 3,4,12, from one vertex to the opposite vertex. What is the shortest possible path length?',sqrt(193),[(13,'Use the straight space diagonal through the interior.'),(19,'Restrict the path to edges.'),(sqrt(241),'Use a longer unfolding.'),(sqrt(265),'Use the longest of the three basic unfoldings.')],[r'Unfold adjacent faces so that a surface path becomes a straight segment in a plane.',r'The three relevant squared distances are (3+4)²+12²=193, (3+12)²+4²=241, and (4+12)²+3²=265.',r'The smallest is 193, giving √193. Each straight segment lies within its unfolded rectangular pair.'],['Unfold the faces crossed by a candidate path.','Compare the three ways to combine two dimensions.'],'Compare feasible unfoldings rather than using the space diagonal.',lambda:sqrt(min((a+b)**2+c*c for a,b,c in [(3,4,12),(3,12,4),(4,12,3)])),'Exhaustive comparison of the three opposite-corner rectangular unfoldings.'),
q(3,r'The plane $x+y+z=9$ cuts the cube $0\le x,y,z\le6$. Find the area of the cross-section.',27*sqrt(3),[(54*sqrt(3),'Use twice the correct hexagon area.'),(18*sqrt(3),'Treat the section as four equilateral triangles.'),(36,'Assume the section is a square face.'),(9*sqrt(3),'Use the side length three rather than the diagonal 3√2.')],[r'The section vertices are the six permutations of (0,3,6). Adjacent vertices differ by (3,-3,0) up to permutation, so the side is 3√2.',r'Symmetry about (3,3,3) makes the section a regular hexagon; its six center triangles are equilateral.',r'The area is 6·(√3/4)(3√2)²=27√3.'],['Find where the plane meets cube edges.','Measure section edges in three dimensions, not in a face projection.'],'Construct and measure an oblique polygonal cross-section.',lambda:6*S.Matrix([0,3,-3]).cross(S.Matrix([-3,3,0])).norm()/2,'Independent cross products of six center-to-vertex triangles.'),
q(4,r'A sphere is inscribed in a cube and another sphere passes through all eight cube vertices. What is the ratio of the larger sphere’s volume to the smaller sphere’s volume?',3*sqrt(3),[(sqrt(3),'Use the radius ratio as the volume ratio.'),(3,'Use area scaling.'),(8,'Assume the outer radius is twice the inner.'),(9,'Square the volume ratio base incorrectly.')],[r'For cube edge a, the inner radius is a/2.',r'The outer radius is half the space diagonal, a√3/2.',r'The radius ratio is √3, so the volume ratio is (√3)³=3√3.'],['Both centers are the cube center.','Volume scales as the cube of a length ratio.'],'Transfer a spatial diagonal ratio to volume.',lambda:(sqrt(3))**3,'Exact radius scaling.',2),
q(5,r'A cone of height 12 is cut by a plane parallel to its base, four units from the vertex. What fraction of the original volume remains after removing the small cone?',F(26,27),[(F(2,3),'Use the height ratio for volume.'),(F(8,9),'Use an area ratio for volume.'),(F(1,27),'Report the removed fraction.'),(F(8,27),'Cube the remaining-height fraction although the remainder is a frustum.')],[r'The removed cone is similar to the original with length scale 4/12=1/3.',r'Its volume fraction is (1/3)³=1/27.',r'The remaining fraction is 1-1/27=26/27.'],['Identify which part is a similar cone.','The remainder is not similar to the original cone.'],'Apply cubic scaling to the correct subsolid.',lambda:1-S.Rational(4,12)**3,'Exact similar-cone volume ratio.',2),
q(6,r'A right circular conical frustum has height 4 and radii 3 and 6. Its volume is $k\pi$. Find k.',84,[(108,'Use a cylinder with the larger radius.'),(36,'Use a cylinder with the smaller radius.'),(63,'Use the average of the squared radii incorrectly.'),(72,'Use an arithmetic average of cylinder volumes without the middle term.')],[r'Extend to the cone vertex. Since the radii have ratio 1:2, the small and full cone heights are 4 and 8.',r'The frustum volume is $\pi(6^2\cdot8-3^2\cdot4)/3$.',r'This is 84π, so k=84.'],['Extend the sloping sides to recover two similar cones.','Subtract their volumes after finding the two heights.'],'Derive a frustum volume by subtraction and similarity.',lambda:S.Rational(4,3)*(3**2+3*6+6**2),'Independent frustum formula.'),
q(7,r'A cylinder of radius 5 contains water to depth 10. A sphere of radius 2 is held entirely below the water surface without spilling. How much does the water level rise?',F(32,75),[(F(8,25),'Omit the factor four-thirds in sphere volume.'),(F(4,5),'Use a radius ratio as a height.'),(F(32,25),'Omit the division by three.'),(F(16,75),'Use a hemisphere volume.')],[r'The submerged sphere displaces its whole volume, 4π·2³/3=32π/3.',r'The added water-level region has constant cross-sectional area 25π.',r'The rise is (32π/3)/(25π)=32/75. The given depth permits full submersion.'],['Use displaced volume rather than the sphere’s projected area.','Divide by the cylinder’s constant cross-sectional area.'],'Translate displacement into a height change.',lambda:(S.Rational(4,3)*2**3)/5**2,'Exact volume balance.',2),
q(8,r'A regular tetrahedron has edge length 6. Find its volume.',18*sqrt(2),[(36*sqrt(2),'Omit the pyramid factor one-third after halving incorrectly.'),(18*sqrt(3),'Use the edge length as the altitude.'),(9*sqrt(2),'Halve the volume twice.'),(36,'Use a rectangular-box model.')],[r'The base is an equilateral triangle of area 9√3. Its center is 2√3 from each base vertex.',r'The perpendicular height is √(6²-(2√3)²)=2√6.',r'The volume is (1/3)(9√3)(2√6)=18√2.'],['The apex projects to the center of the equilateral base.','Find the spatial altitude from an edge and the base circumradius.'],'Combine a planar center distance with a pyramid altitude.',lambda:abs(S.Matrix([[6,0,0],[3,3*sqrt(3),0],[3,sqrt(3),2*sqrt(6)]]).det())/6,'Independent tetrahedron determinant.'),
q(9,r'Three mutually adjacent faces of a rectangular box have areas 6,10,15. Find its volume.',30,[(60,'Multiply two face areas without removing the repeated edge.'),(900,'Report the square of the volume.'),(31,'Add the face areas.'),(15,'Use the largest face area.')],[r'Let the dimensions be a,b,c, so ab=6,ac=10,bc=15.',r'Multiplying gives (abc)²=6·10·15=900.',r'Positive dimensions imply volume abc=30. The dimensions 2,3,5 verify existence.'],['Multiply the three face-area equations.','Each edge then occurs twice.'],'Recover a three-dimensional quantity from pairwise products.',lambda:2*3*5,'Independent dimensions 2,3,5 satisfy all face areas.',2),
q(10,r'A cube is painted on all six faces and cut into 64 congruent small cubes. How many small cubes have exactly two painted faces?',24,[(8,'Count corner cubes, which have three painted faces.'),(32,'Include edge endpoints.'),(16,'Count only a subset of the twelve edges.'),(48,'Count painted faces rather than small cubes.')],[r'There are four small cubes along each edge.',r'Exactly two painted faces occur at the two noncorner positions on each of the twelve edges.',r'The count is 12(4-2)=24. These positions are disjoint across edges.'],['Classify cubes by whether they lie at a face, edge, or vertex.','Remove both endpoints of each edge.'],'Count spatial boundary types without double-counting corners.',lambda:sum(sum(t in [0,3] for t in [x,y,z])==2 for x in range(4) for y in range(4) for z in range(4)),'Independent coordinate enumeration of all 64 cubes.',2),
q(11,r'A cylindrical hole of radius 3 is drilled through the center of a sphere of radius 5. The remaining solid has volume $k\pi$. Find k.',F(256,3),[(F(500,3),'Use the whole sphere.'),(F(392,3),'Subtract a cylinder of height four and ignore the spherical caps.'),(128,'Omit part of the spherical caps.'),(F(244,3),'Subtract a cylinder with the full sphere diameter, ignoring caps.')],[r'The remaining ring extends from z=-4 to z=4, since 5²-3²=4².',r'At height z, its annular cross-section has area π[(25-z²)-9]=π(16-z²).',r'These are exactly the cross-sections of a sphere of radius four. By Cavalieri’s principle, the volume is 4π·4³/3=256π/3.'],['Compare horizontal cross-sections rather than subtracting a full cylinder alone.','The hole also removes portions of the spherical caps.'],'Use equal cross-sections to identify a nonobvious equivalent solid.',lambda:S.integrate(S.pi*(16-S.Symbol('z')**2),(S.Symbol('z'),-4,4))/S.pi,'Independent symbolic volume integral; the learner solution uses Cavalieri, not calculus.'),
q(12,r'What is the largest squared distance between midpoints of two distinct edges of a unit cube?',2,[(3,'Use opposite vertices rather than edge midpoints.'),(F(3,2),'Use midpoints of nonparallel edges.'),(1,'Restrict both midpoints to one face.'),(F(5,2),'Allow a coordinate difference impossible for two edge midpoints.')],[r'Each edge midpoint has one coordinate 1/2 and two coordinates in {0,1}.',r'For parallel edges, squared distance is at most 1²+1²=2, attained by (1/2,0,0) and (1/2,1,1).',r'For nonparallel edges, it is at most 1+1/4+1/4=3/2. Thus the maximum is 2.'],['Classify the pair according to whether the edges are parallel.','Bound the coordinate differences in each case.'],'Prove a spatial maximum by complete geometric cases.',lambda:max(a.distance(b)**2 for a,b in combinations([S.Point3D(*coords) for coords in [(F(1,2),y,z) for y in [0,1] for z in [0,1]]+[(x,F(1,2),z) for x in [0,1] for z in [0,1]]+[(x,y,F(1,2)) for x in [0,1] for y in [0,1]]],2)),'Exhaustive exact distances among the twelve edge midpoints.'),
q(13,r'A right circular cylinder is inscribed in a cone of radius 6 and height 12, with its lower base in the cone’s base plane. What is the largest possible cylinder volume divided by π?',64,[(72,'Use half the cone height as an unsupported optimum.'),(144,'Use the cone volume itself.'),(108,'Assume the cylinder can keep the full radius at positive height.'),(32,'Use height eight rather than the maximizing height.')],[r'If t is the cylinder height divided by 12, similarity gives radius 6(1-t). Its volume divided by π is 432t(1-t)².',r'The three nonnegative numbers t,(1-t)/2,(1-t)/2 sum to one. AM–GM gives t(1-t)²≤4/27.',r'The bound is attained at t=1/3, giving height four, radius four, and volume 64π.'],['Use similarity to express radius in terms of height.','Split the repeated factor so that three nonnegative quantities have fixed sum.'],'Combine a spatial similarity constraint with an attainable product bound.',lambda:432*S.Rational(1,3)*(1-S.Rational(1,3))**2,'Independent derivative factorization confirms the unique interior maximum; AM–GM supplies the noncalculus proof.'),
q(14,r'Two spheres of radius 3 fit exactly in a cylinder, touching each other, its curved surface, and its two end planes. What fraction of the cylinder is unoccupied?',F(1,3),[(F(2,3),'Report the occupied fraction.'),(F(1,2),'Treat each sphere as half its bounding cylinder.'),(F(1,4),'Use diameter counts as volume fractions.'),(F(3,4),'Subtract a radius ratio rather than volumes.')],[r'The cylinder has radius three and height twelve, so volume 108π.',r'The two spheres occupy $2(4π·27/3)=72π$.',r'The unoccupied fraction is (108-72)/108=1/3.'],['Determine the cylinder dimensions from the tangencies.','Subtract volumes before forming the fraction.'],'Translate spatial packing constraints into volume comparison.',lambda:1-2*S.Rational(4,3)*3**3/(3**2*12),'Exact volume ratio.',2)]
e=[
q(101,r'Find the shortest surface path between opposite vertices of a cube of edge 2.',2*sqrt(5),[(2*sqrt(3),'Use the interior space diagonal.'),(6,'Restrict travel to edges.'),(4,'Ignore one unfolded dimension.'),(4*sqrt(2),'Use an unnecessarily long net.')],[r'Unfold two adjacent faces into a rectangle with sides four and two. Opposite cube vertices become opposite rectangle corners.',r'The straight segment has length √(4²+2²)=2√5 and lies in the unfolded rectangle, so it is a valid surface path.',r'Every choice of the pair of combined dimensions is congruent in a cube. Other edge-only routes are longer.',r'The interior space diagonal is shorter, but is forbidden by the surface constraint. The model must preserve where the ant can walk.'],['Flatten two adjacent faces while preserving distances on each face.','Use a straight segment in the resulting rectangle.'],'Explain a feasible unfolding model.',lambda:sqrt(4**2+2**2),'Independent flat-net distance.',2),
q(102,r'A pyramid is cut parallel to its base halfway from its vertex to the base. What fraction of its volume lies between the cut and the base?',F(7,8),[(F(1,2),'Use linear scaling for volume.'),(F(3,4),'Use area scaling.'),(F(1,8),'Report the removed small pyramid.'),(F(1,4),'Square the scale and report the wrong portion.')],[r'The small pyramid at the vertex is similar to the original with every length halved.',r'Its base area is one quarter as large and its height one half as large, so its volume is one eighth.',r'The region between the cut and base is the remainder, seven eighths.',r'This derives cubic volume scaling from the area-times-height formula rather than treating the exponent three as a memorized rule.'],['Identify the similar pyramid at the vertex.','Track both the base area and the height.'],'Derive cubic scaling and subtract the correct region.',lambda:1-S.Rational(1,2)**3,'Independent area scale times height scale.',2)]
finish('spatial-geometry','Spatial geometry: nets, sections & volume','Geometry','solids geometric-constructions ratio-geometry',36,'511–573',
 [r'A solid can be studied through a plane section, a flat net, or a volume comparison. Choose the model that preserves the quantity asked for. A surface distance is preserved by unfolding; a volume can be compared through cross-sections; an oblique section needs its actual three-dimensional edge lengths.',r'The apparent difficulty often comes from looking at the wrong two-dimensional picture. A projection may shorten a segment, while a net preserves it. State which representation you are using before reading lengths from it.'],
 [section('Separate interior, surface, and edge paths',r'A box’s space diagonal uses all three squared dimensions and passes through the interior. An edge path adds edge lengths. A shortest surface path generally does neither: unfold the crossed faces and use a straight segment in the resulting plane.',r'For opposite corners of a rectangular box, compare the three basic unfoldings obtained by combining two dimensions and retaining the third. Check that the segment remains within the unfolded faces. A candidate drawn across a gap or an extension of a face is not a permissible route.',r'Coordinates are also useful for classifying spatial configurations. Edge midpoints have one coordinate fixed at one half. Distinguishing parallel and nonparallel edge pairs gives a complete maximum-distance argument without checking every pair by hand.'),
 section('Construct the section before measuring it',r'A plane section’s vertices occur where the plane meets the solid’s edges. Solve these intersections first, then determine their cyclic order. For a symmetric cube section, the six vertices can reveal a regular hexagon, but its side is often a face diagonal fragment rather than the visible coordinate difference.',r'A regular pyramid’s altitude reaches the center of its base. Find the base center-to-vertex distance in the base plane, then use a spatial right triangle with a sloping edge. A slant height, an edge, and a perpendicular height are distinct lengths.',r'For a frustum, extend the sides to the original vertex and recover two similar cones or pyramids. Similarity relates both radii and heights. Subtract the two full volumes; averaging the two base areas without a derivation generally omits the necessary middle term.'),
 section('Volume comparisons retain structure',r'If lengths scale by k, areas scale by k² and volumes by k³. A parallel cut creates a small similar solid at the vertex; the remaining frustum is not itself similar to the original. Apply scaling to the small solid and subtract its volume afterward.',r'Displacement preserves volume. A fully submerged object raises water in a cylinder by its volume divided by the cylinder’s cross-sectional area. Check that the stated depth and container allow the assumed submersion and that no spilling changes the volume balance.',r'Cavalieri’s principle compares solids with equal cross-sectional areas at every height. In the drilled-sphere problem, each annular section matches a disk of a smaller sphere. This avoids an incorrect subtraction of a full cylinder that ignores the removed caps. For optimization, similarity can express an inscribed solid’s dimensions with one parameter; an inequality then gives a bound and an attainable equality configuration.')],
 ['Choose between unfolding, cross-sections, and volume models.','Measure oblique sections and perpendicular heights correctly.','Use similarity and equality cases to solve spatial comparisons and maxima.'],
 [r'Unfold face distances without changing lengths inside each face.',r'Use base-center geometry and a spatial right triangle to derive a pyramid altitude.',r'Multiply an area scale by a height scale to derive cubic volume scaling.'],
 'A projected segment, a surface path, and a straight distance through a solid are different objects. The shortest path must stay in the allowed region.',e,p,
 dict(prompt=r'A cone of height 15 is cut parallel to its base six units from the vertex. What fraction of the volume remains below the cut?',answer=r'$117/125$.',steps=[r'The removed cone has length scale 6/15=2/5 and volume scale 8/125.',r'The remainder is 1-8/125=117/125.']),
 ['surface unfolding','oblique cross-sections','Cavalieri comparison','similar-solid scaling'],
 [(r'd^2=a^2+b^2+c^2','Space diagonal','measuring the straight diagonal of a rectangular box','a,b,c are mutually perpendicular edge lengths; this is not a surface path.'),(r'V_1/V_2=k^3','Similar-solid volume scaling','converting a common length scale into a volume ratio','The solids are similar and k is the ratio of corresponding lengths.'),(r'V_{\rm frustum}=\frac{\pi h}{3}(R^2+Rr+r^2)','Conical frustum volume','finding volume between two parallel circular sections of a cone','R and r are the section radii and h is their perpendicular separation.'),(r'\Delta h=V_{\rm displaced}/A','Displacement height','finding a water-level rise in a vessel with constant horizontal area','A is constant over the level change, with no spilling and the stated submerged volume.')], 'solids')
